%% Demonstrate the Gaussian ODF functions%% See also% GaussianPDF, GaussianCPDFx     = linspace(-3,3);mu    = 0;sigma = 1;pDF   = GaussianPDF( x, mu, sigma );cPDF  = GaussianCPDF( x, mu, sigma );t     = sprintf('Gaussian PDF for mu = %8.1f and sigma = %8.1f',mu,sigma);Plot2D( x, pDF, 'Value', 'pdf', t );Plot2D( x, cPDF, 'Value', 'pdf', t );%% Copyright% Copyright (c) 2023 Princeton Satellite Systems, Inc.% All rights reserved.